SELECT COUNT(*) FROM file_node
WHERE parent_id = #{parentId} AND deleted = 0

    AND space_type = 3 AND project_id = #{projectId}
    AND (space_type IS NULL OR space_type = 1) AND team_id IS NULL AND (#{userId} IS NULL OR upload_user_id = #{userId})
    AND team_id = #{teamId}

SELECT COUNT(*) FROM file_node
WHERE deleted = 0

    AND team_id IS NULL AND upload_user_id = #{userId}
    AND team_id = #{teamId}

AND original_name LIKE CONCAT(#{keyword}, '%')

SELECT original_name FROM file_node
WHERE parent_id = #{parentId} AND file_type = #{fileType} AND deleted = 0

    AND space_type = 3 AND project_id = #{projectId}
    AND (space_type IS NULL OR space_type = 1) AND team_id IS NULL AND (#{userId} IS NULL OR upload_user_id = #{userId})
    AND team_id = #{teamId}

SELECT uuid_name FROM file_node WHERE deleted IN (0, 1) AND file_type = 1 AND id IN
#{fileId}
AND uuid_name IS NOT NULL AND uuid_name != ''

WITH RECURSIVE descendants AS ( SELECT id, parent_id FROM file_node WHERE deleted IN (0, 1) AND id IN
#{rootId}
UNION ALL SELECT child.id, child.parent_id FROM file_node child INNER JOIN descendants parent ON child.parent_id = parent.id WHERE child.deleted IN (0, 1) ) SELECT id FROM descendants

mapper.update:
UPDATE file_node
SET original_name = CASE id

    WHEN #{fileId} THEN #{originalName}

END, modify_time = NOW()
WHERE id IN

    #{fileId}

UPDATE file_node
SET deleted = 1, modify_time = NOW(), deleted_user_id = #{userId}
WHERE deleted IN (0, 1) AND id IN

    #{fileId}

UPDATE file_node
SET deleted = 2, modify_time = NOW(), deleted_user_id = #{userId}
WHERE deleted IN (0, 1) AND id IN

    #{fileId}

mapper.select:
SELECT COALESCE(SUM(file_size), 0)
FROM file_node
WHERE deleted IN (0, 1) AND file_type = 1

    AND space_type = 3 AND project_id = #{projectId}
    AND space_type = 2 AND team_id = #{teamId}
    AND (space_type IS NULL OR space_type = 1) AND team_id IS NULL AND upload_user_id = #{userId}

SELECT scope_key AS scopeKey, COALESCE(SUM(file_size), 0) AS totalBytes FROM file_node WHERE id IN
#{fileId}
AND file_size IS NOT NULL GROUP BY scope_key

SELECT f.id
FROM file_node f
WHERE f.deleted = 1
  AND f.modify_time < #{cutoff}
  AND NOT EXISTS (
        SELECT 1 FROM file_node p
        WHERE p.id = f.parent_id AND p.deleted = 1
  )
LIMIT #{limit}

SELECT id FROM file_node
WHERE deleted = 2
  AND modify_time < #{cutoff}
LIMIT #{limit}
